public class Ex10SelfBounded {
    static abstract class SelfBounded<T extends SelfBounded<T>> {
        abstract T self();
        T copy() { return self(); }
    }
    static class Concrete extends SelfBounded<Concrete> {
        Concrete self() { return this; }
        void special() { System.out.println("Concrete.special()"); }
    }
    public static void main(String[] args) {
        Concrete c = new Concrete();
        c.copy().special();
        System.out.println("self-bounded fluent ok");
    }
}
